<?php
require_once __DIR__.'/includes/db.php';
$matchId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT) ?: filter_input(INPUT_POST,'pertandingan_id',FILTER_VALIDATE_INT);
$q=$pdo->prepare('SELECT * FROM pertandingan WHERE id=? AND status="akan_datang"'); $q->execute([$matchId?:0]); $match=$q->fetch();
if(!$match){http_response_code(404); exit('Pertandingan tidak ditemukan atau tidak tersedia. <a href="pertandingan.php">Kembali</a>');}
$q=$pdo->prepare('SELECT * FROM kategori_tiket WHERE pertandingan_id=? AND stok>0 ORDER BY harga'); $q->execute([$match['id']]); $categories=$q->fetchAll();
$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
  $nama=trim($_POST['nama']??''); $email=trim($_POST['email']??''); $kategoriId=filter_input(INPUT_POST,'kategori_id',FILTER_VALIDATE_INT); $jumlah=filter_input(INPUT_POST,'jumlah',FILTER_VALIDATE_INT); $phone=trim($_POST['no_telepon']??'');
  if($nama==='' || mb_strlen($nama)>120) $errors[]='Nama wajib diisi (maksimal 120 karakter).';
  if(!filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($email)>150) $errors[]='Masukkan alamat email yang valid.';
  if(!$kategoriId || !$jumlah || $jumlah<1 || $jumlah>10) $errors[]='Pilih kategori dan jumlah tiket 1 sampai 10.';
  if(!$errors){
    try { $pdo->beginTransaction(); $q=$pdo->prepare('SELECT * FROM kategori_tiket WHERE id=? AND pertandingan_id=? FOR UPDATE'); $q->execute([$kategoriId,$match['id']]); $cat=$q->fetch(); if(!$cat || (int)$cat['stok']<$jumlah) throw new RuntimeException('Stok tiket tidak mencukupi.');
      $code='LK-'.strtoupper(bin2hex(random_bytes(4))); $total=(int)$cat['harga']*$jumlah;
      $q=$pdo->prepare('INSERT INTO pemesanan (kode_pemesanan,nama_pemesan,email,no_telepon,total_harga,status) VALUES (?,?,?,?,?,"menunggu")'); $q->execute([$code,$nama,$email,$phone,$total]); $bookingId=(int)$pdo->lastInsertId();
      $q=$pdo->prepare('INSERT INTO detail_pemesanan (pemesanan_id,pertandingan_id,kategori_tiket_id,jumlah,harga_satuan,subtotal) VALUES (?,?,?,?,?,?)'); $q->execute([$bookingId,$match['id'],$kategoriId,$jumlah,$cat['harga'],$total]);
      $q=$pdo->prepare('UPDATE kategori_tiket SET stok=stok-? WHERE id=?'); $q->execute([$jumlah,$kategoriId]); $pdo->commit(); header('Location: berhasil.php?kode='.urlencode($code)); exit;
    } catch(RuntimeException $ex){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$ex->getMessage();} catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Pemesanan gagal disimpan. Coba lagi.';}
  }
}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pesan Tiket | LagaKita</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/includes/navbar.php'; ?><main class="container py-5"><div class="row justify-content-center"><div class="col-lg-7"><p class="eyebrow">FORM PEMESANAN</p><h1 class="fw-bold">Pesan tiket</h1><p class="text-muted mb-4"><?= e($match['tim_tuan_rumah']) ?> vs <?= e($match['tim_tamu']) ?> · <?= e(date('d M Y H:i',strtotime($match['tanggal']))) ?> WIB</p><?php if($errors): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" data-confirm class="card match-card"><div class="card-body p-4"><input type="hidden" name="pertandingan_id" value="<?= (int)$match['id'] ?>"><div class="mb-3"><label class="form-label" for="nama">Nama lengkap</label><input class="form-control" id="nama" name="nama" maxlength="120" required value="<?= e($_POST['nama']??'') ?>"></div><div class="mb-3"><label class="form-label" for="email">Email</label><input class="form-control" id="email" name="email" type="email" maxlength="150" required value="<?= e($_POST['email']??'') ?>"></div><div class="mb-3"><label class="form-label" for="no_telepon">No. telepon (opsional)</label><input class="form-control" id="no_telepon" name="no_telepon" maxlength="30" value="<?= e($_POST['no_telepon']??'') ?>"></div><div class="row"><div class="col-md-8 mb-3"><label class="form-label" for="kategori_id">Kategori tiket</label><select class="form-select" id="kategori_id" name="kategori_id" required><option value="">Pilih kategori</option><?php foreach($categories as $cat): ?><option value="<?= (int)$cat['id'] ?>" <?= (($_POST['kategori_id']??'')==$cat['id'])?'selected':'' ?>><?= e($cat['nama_kategori']) ?> — <?= rupiah($cat['harga']) ?> (stok <?= (int)$cat['stok'] ?>)</option><?php endforeach; ?></select></div><div class="col-md-4 mb-3"><label class="form-label" for="jumlah">Jumlah</label><input class="form-control" type="number" min="1" max="10" id="jumlah" name="jumlah" required value="<?= e($_POST['jumlah']??1) ?>"></div></div><div class="alert alert-info small">Pemesanan dicatat dengan status <strong>menunggu</strong>. Pembayaran belum terintegrasi.</div><button class="btn btn-success btn-lg w-100" type="submit" <?= !$categories?'disabled':'' ?>>Simpan pemesanan</button></div></form></div></div></main><?php include __DIR__.'/includes/footer.php'; ?></body></html>
